allerVersPageProduitParNom(PRODUCTS.faible.name);
lireStockProduitUI().then(stockAvant => {
  const quantiteTropGrande = stockAvant + 2;
  saisirQuantite(quantiteTropGrande);
  ajouterAuPanierEtAttendre("addTooMuch").then(({
    response
  }) => {
    const status = response === null || response === void 0 ? void 0 : response.statusCode;
    if (status === 200) {
      lireStockProduit(PRODUCTS.faible.id).then(stockApres => {
        signalerAnomalie("ANO-BACK-02", "DEFECT HIGH — quantité supérieure au stock acceptée", `Attendu : ajout refusé | Observé : HTTP 200 | Stock avant = ${stockAvant} | Stock après = ${stockApres}`);
      });
      return;
    }
    expect(status).to.be.oneOf([400, 401, 403, 409, 422]);
  });
  cy.url().should("not.include", "/cart");
  cy.log("✅ TEST 6 — quantité supérieure au stock refusée");
});

allerVersPageProduitParNom(PRODUCTS.rupture.name);
cy.get("body").then($body => {
  const boutonExiste = $body.find(_selectors.selectors.addToCartButton).length > 0;
  if (!boutonExiste) {
    cy.log("✅ TEST 7 — Bouton absent pour produit en rupture");
    return;
  }
  cy.get(_selectors.selectors.addToCartButton).then($btn => {
    if ($btn.is(":disabled")) {
      cy.log("✅ TEST 7 — Bouton désactivé pour produit en rupture");
      return;
    }
    cy.wrap($btn).click();
    lireStockProduit(PRODUCTS.rupture.id).then(stock => {
      signalerAnomalie("ANO-BACK-03", "DEFECT HIGH — produit en rupture toujours ajoutable", `Attendu : bouton absent ou désactivé | Observé : bouton actif, stock = ${stock}`);
    });
  });
});

